%[text] %[text:anchor:T_1FFD3858] # High Voltage Battery - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Discharge
mdl = "BatteryHV_TestModel";
load_system(mdl)

% Load model parameters.
BatteryHV_TestModelSetup

% Select battery model.
BatteryHV_setRefsub_SystemTable %[output:3eaa702d]
% Setup simulation case.
BatteryHV_setSimCase_Discharge( ... %[output:group:6abde30a] %[output:1c55ead0]
  CRate = 0.1, ...  Positive value for discharge %[output:1c55ead0]
  StateOfCharge_pct = 50 ) %[output:group:6abde30a] %[output:1c55ead0]
set_param(mdl, StopTime="3600")
% Run simulation.
simOut = sim(mdl);

% Collect logged signals and visualize.
% The basic version of the battery block does not simulate battery temperature.
logged_signals = extractTimetable(simOut.logsout);
BatteryHV_ResultsPlot(Timetable=logged_signals); %[output:40b1bd09]
